import type { ReactElement } from 'react'
import { Maskicon } from '@metamask/design-system-react'
import Skeleton from '@mui/material/Skeleton'
import { isAddress } from 'ethers'

export interface IdenticonProps {
  address: string
  size?: number
}

const Identicon = ({ address, size = 40 }: IdenticonProps): ReactElement => {
  if (!isAddress(address)) {
    return <Skeleton variant="rounded" width={size} height={size} />
  }

  return <Maskicon address={address} size={size} style={{ borderRadius: '0.5rem', display: 'block' }} />
}

export default Identicon
